import { useState } from "react";
import "./App.css";

function App() {
  const [form, setForm] = useState({
    type: "",
    amount: "",
    oldbalanceOrg: "",
    newbalanceOrig: "",
    nameDest: "",
    oldbalanceDest: "",
    newbalanceDest: "",
    threshold: 0.5,
  });

  const [result, setResult] = useState(null);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handlePredict = async () => {
  console.log("🚀 handlePredict lancé !");
  try {
    const res = await fetch("http://127.0.0.1:8000/predict", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...form,
        amount: parseFloat(form.amount),
        oldbalanceOrg: parseFloat(form.oldbalanceOrg),
        newbalanceOrig: parseFloat(form.newbalanceOrig),
        oldbalanceDest: parseFloat(form.oldbalanceDest),
        newbalanceDest: parseFloat(form.newbalanceDest),
        threshold: parseFloat(form.threshold),
      }),
    });
    console.log("📡 Requête envoyée, réponse arrivée :", res);

    if (!res.ok) {
      const err = await res.json();
      console.error("Erreur API :", err);
      return;
    }

    const data = await res.json();
    console.log("📦 Réponse JSON :", data);
    setResult(data);
  } catch (err) {
    console.error("❌ Exception fetch :", err);
  }
};

  return (
    <div className="container">
      <h1>Fraud Detection</h1>

      <div className="form-container">
        {Object.keys(form).map((key) => (
          <div className="input-group" key={key}>
            <label>{key}</label>
            <input name={key} value={form[key]} onChange={handleChange} />
          </div>
        ))}

        <button onClick={handlePredict}>Predict</button>
      </div>

      {result && (
        <div className="result">
          <h2>Result:</h2>
          <p><strong>Prediction:</strong> {result.label}</p>
          <p><strong>Probability:</strong> {result.probability.toFixed(4)}</p>
        </div>
      )}
    </div>
  );
}

export default App;
